  + `On\\s.+\\swrote${WORD_END}\\s*:`
  + `|Le\\s.+\\sa\\s+écrit${WORD_END}\\s*:`
  + `|Am\\s.+\\sschrieb${WORD_END}(?:\\s.*)?:`
  + `|El\\s.+\\sescribió${WORD_END}\\s*:`
  + `|Il\\s.+\\sha\\s+scritto${WORD_END}\\s*:`
  + `|Em\\s.+\\sescreveu${WORD_END}\\s*:`
  + `|Op\\s.+\\sschreef${WORD_END}(?:\\s.*)?:`
