+
+/// Select body candidates and identify related resources before attachment filtering.
+fn select_parts<'a>(part: &'a Value, depth: usize, related: bool, out: &mut Selection<'a>) {
+    if depth > MAX_PAYLOAD_DEPTH { return; }
+    let cid = json_header_value(part, "Content-ID");
+    let disposition = json_header_value(part, "Content-Disposition");
+    let resource = related && !cid.trim().is_empty()
+        && part["body"]["attachmentId"].as_str().is_some()
+        && !disposition.trim_start().to_ascii_lowercase().starts_with("attachment");
+    if resource { out.inline.push(part); return; }
+    if is_attachment_part(part) { out.attachments = true; return; }
+    let mime = part["mimeType"].as_str().unwrap_or_default();
+    if mime.eq_ignore_ascii_case("text/plain") && out.plain.is_none() { out.plain = Some(part); }
+    if mime.eq_ignore_ascii_case("text/html") && out.html.is_none() { out.html = Some(part); }
+    if mime.to_ascii_lowercase().starts_with("multipart/") {
